--
-- Table structure for table `member`
--

DROP TABLE IF EXISTS `member`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `member` (
  `id` int NOT NULL AUTO_INCREMENT,
  `memberId` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `memberName` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fatherName` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateOfBirth` datetime(3) DEFAULT NULL,
  `photo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `residentialAddress` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mobile` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `residentialTelephone` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `panCardNo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `designation` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `companyName` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `companyAddress` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `companyTelephone` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `packetNo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `dateOfJoining` datetime(3) DEFAULT NULL,
  `validityFrom` datetime(3) DEFAULT NULL,
  `validityTo` datetime(3) DEFAULT NULL,
  `aadharNo` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `district` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `isShow` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `specialDates` json DEFAULT NULL,
  `statusReason` text COLLATE utf8mb4_unicode_ci,
  `statusActionBy` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `statusActionAt` datetime(3) DEFAULT NULL,
  `state` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `city` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Member_memberId_key` (`memberId`),
  KEY `Member_isActive_idx` (`isActive`),
  KEY `Member_state_idx` (`state`),
  KEY `Member_district_idx` (`district`),
  KEY `Member_city_idx` (`city`),
  KEY `Member_isShow_idx` (`isShow`)
) ENGINE=InnoDB AUTO_INCREMENT=12040 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

