  KEY `MemberRenewal_memberId_idx` (`memberId`),
  CONSTRAINT `MemberRenewal_memberId_fkey` FOREIGN KEY (`memberId`) REFERENCES `member` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
